<?php
$title='Home';
if($page==='login' && $_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$name=trim((string)($_POST['username']??''));$pass=(string)($_POST['password']??'');
 $q=$db->prepare('SELECT id,password_hash FROM users WHERE username=?');$q->execute([$name]);$u=$q->fetch();
 if($u&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];notice('Welcome back!');go('/');}
 notice('Invalid username or password.','error');go('/Login.aspx');
}
if($page==='register'&&$_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$name=trim((string)($_POST['username']??''));$pass=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm']??'');
 if(!preg_match('/^[A-Za-z0-9_]{3,20}$/',$name)){notice('Username must be 3–20 letters, numbers or underscores.','error');go('/Register.aspx');}
 if(strlen($pass)<8||$pass!==$confirm){notice('Passwords must match and contain at least 8 characters.','error');go('/Register.aspx');}
 try{$q=$db->prepare('INSERT INTO users(username,password_hash) VALUES(?,?)');$q->execute([$name,password_hash($pass,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user_id']=(int)$db->lastInsertId();notice('Account created. Welcome!');go('/');}
 catch(PDOException $e){if($e->getCode()==='23000'){notice('That username is already taken.','error');go('/Register.aspx');}throw $e;}
}
if($page==='logout'){$_SESSION=[];session_destroy();go('/');}
if($page==='forum'&&$_SERVER['REQUEST_METHOD']==='POST'){
 login_required();check_csrf();$heading=trim((string)($_POST['title']??''));$body=trim((string)($_POST['body']??''));
 if($heading!==''&&$body!==''){$q=$db->prepare('INSERT INTO forum_topics(user_id,title) VALUES(?,?)');$q->execute([$currentUser['id'],$heading]);$db->prepare('INSERT INTO forum_replies(topic_id,user_id,body) VALUES(?,?,?)')->execute([(int)$db->lastInsertId(),$currentUser['id'],$body]);notice('Topic posted.');}
 go('/Forum/Default.aspx');
}
if($page==='item'&&$_SERVER['REQUEST_METHOD']==='POST'){
 login_required();check_csrf();$itemId=(int)($_GET['id']??0);
 $q=$db->prepare('INSERT IGNORE INTO inventory(user_id,item_id) VALUES(?,?)');$q->execute([$currentUser['id'],$itemId]);notice('Inventory updated.');go('/Item.aspx?id='.$itemId);
}
if($page==='home'){$title='Home';$games=$db->query('SELECT id,title,description,visits FROM games ORDER BY visits DESC,id DESC LIMIT 6')->fetchAll();}
elseif($page==='games'){$title='Games';if(isset($_GET['id'])){$q=$db->prepare('SELECT * FROM games WHERE id=?');$q->execute([(int)$_GET['id']]);$game=$q->fetch();if($game)$db->prepare('UPDATE games SET visits=visits+1 WHERE id=?')->execute([$game['id']]);}else{$games=$db->query('SELECT g.*,u.username FROM games g LEFT JOIN users u ON u.id=g.creator_id ORDER BY g.id DESC')->fetchAll();}}
elseif($page==='catalog'){$title='Catalog';$type=(string)($_GET['type']??'all');$types=['all','hat','shirt','pants','tshirt','face','head'];if(!in_array($type,$types,true))$type='all';$q=$type==='all'?$db->query('SELECT * FROM catalog_items ORDER BY id DESC'):$db->prepare('SELECT * FROM catalog_items WHERE type=? ORDER BY id DESC');if($type!=='all')$q->execute([$type]);$items=$q->fetchAll();}
elseif($page==='people'){$title='People';$users=$db->query('SELECT id,username,blurb,last_seen FROM users ORDER BY last_seen DESC LIMIT 50')->fetchAll();}
elseif($page==='user'){$id=(int)($_GET['id']??($currentUser['id']??0));$q=$db->prepare('SELECT * FROM users WHERE id=?');$q->execute([$id]);$profile=$q->fetch();$title=$profile?$profile['username']:'User not found';if($profile){$q=$db->prepare('SELECT c.name,c.type FROM inventory i JOIN catalog_items c ON c.id=i.item_id WHERE i.user_id=?');$q->execute([$id]);$owned=$q->fetchAll();}}
elseif($page==='item'){$q=$db->prepare('SELECT * FROM catalog_items WHERE id=?');$q->execute([(int)($_GET['id']??0)]);$item=$q->fetch();$title=$item?$item['name']:'Item not found';}
elseif($page==='forum'){$title='Forum';$topics=$db->query('SELECT t.id,t.title,t.created_at,u.username,COUNT(r.id) replies FROM forum_topics t JOIN users u ON u.id=t.user_id LEFT JOIN forum_replies r ON r.topic_id=t.id GROUP BY t.id ORDER BY t.id DESC LIMIT 50')->fetchAll();}
elseif($page==='login')$title='Login';elseif($page==='register')$title='Register';elseif($page==='404')$title='Page not found';
require __DIR__.'/../inc/header.php';
?>
<?php if($page==='home'):?>
<section id="SplashContainer"><aside id="SignInPane"><?php if($currentUser):?><h2>Welcome, <?=e($currentUser['username'])?>!</h2><p>Explore the virtual playworld.</p><a class="Button" href="/Games.aspx">Play Games</a><?php else:?><h2>Member Login</h2><form method="post" action="/Login.aspx"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Character Name<input name="username" required maxlength="20"></label><label>Password<input type="password" name="password" required></label><button class="Button">Login</button></form><p><a href="/Register.aspx">Register for free</a></p><?php endif;?></aside><div id="RobloxAtAGlance"><h1>ROBLOX Virtual Playworld</h1><h2>Build. Play. Share.</h2><ul id="ThingsToDo"><li><b>Build your personal Place</b><br>Create buildings, vehicles and scenery.</li><li><b>Meet new friends online</b><br>Visit profiles and discover the community.</li><li><b>Explore player-made games</b><br>Find something fun to play.</li></ul></div></section>
<section class="Panel"><h2>Cool Places</h2><div class="tile-grid"><?php foreach($games as $g):?><article class="tile"><a href="/Games.aspx?id=<?=(int)$g['id']?>"><b><?=e($g['title'])?></b></a><p><?=e($g['description'])?></p><small><?=(int)$g['visits']?> visits</small></article><?php endforeach;?><?php if(!$games):?><p>No places yet. Add games in MariaDB to show them here.</p><?php endif;?></div><a href="/Games.aspx">See all games »</a></section>
<?php elseif($page==='games'):?><section class="Panel"><h1>Games</h1><?php if(isset($_GET['id'])):?><?php if(!$game):?><p>Place not found.</p><?php else:?><h2><?=e($game['title'])?></h2><p><?=nl2br(e($game['description']))?></p><p>Visits: <?=(int)$game['visits']+1?></p><p class="notice">Game directory is active. Legacy client launching requires a separate client/server integration.</p><?php endif;?><?php else:?><div class="tile-grid"><?php foreach($games as $g):?><article class="tile"><a href="/Games.aspx?id=<?=(int)$g['id']?>"><b><?=e($g['title'])?></b></a><p><?=e($g['description'])?></p><small>by <?=e($g['username']??'Player')?></small></article><?php endforeach;?></div><?php endif;?></section>
<?php elseif($page==='catalog'):?><section class="Panel"><h1>Catalog</h1><div class="tabs"><?php foreach($types as $t):?><a href="/Catalog.aspx?type=<?=e($t)?>"><?=e(ucfirst($t))?></a><?php endforeach;?></div><div class="tile-grid"><?php foreach($items as $it):?><article class="tile"><a href="/Item.aspx?id=<?=(int)$it['id']?>"><b><?=e($it['name'])?></b></a><p><?=e($it['description'])?></p><small><?=(int)$it['price']?> tickets</small></article><?php endforeach;?><?php if(!$items):?><p>Catalog is empty.</p><?php endif;?></div></section>
<?php elseif($page==='people'):?><section class="Panel"><h1>People</h1><table class="Grid"><tr><th>Name</th><th>About</th><th>Status</th></tr><?php foreach($users as $u):?><tr><td><a href="/User.aspx?id=<?=(int)$u['id']?>"><?=e($u['username'])?></a></td><td><?=e($u['blurb'])?></td><td><?=strtotime($u['last_seen']??'2000-01-01')>time()-300?'Online':'Offline'?></td></tr><?php endforeach;?></table></section>
<?php elseif($page==='user'):?><section class="Panel"><?php if(!$profile):?><h1>User not found</h1><?php else:?><h1><?=e($profile['username'])?></h1><p><?=nl2br(e($profile['blurb']))?></p><p>Joined <?=e($profile['created_at'])?></p><h2>Inventory</h2><ul><?php foreach($owned as $it):?><li><?=e($it['name'])?> (<?=e($it['type'])?>)</li><?php endforeach;?><?php if(!$owned):?><li>No items yet.</li><?php endif;?></ul><?php endif;?></section>
<?php elseif($page==='item'):?><section class="Panel"><?php if(!$item):?><h1>Item not found</h1><?php else:?><h1><?=e($item['name'])?></h1><p><?=e($item['description'])?></p><p>Type: <?=e($item['type'])?> · Price: <?=(int)$item['price']?> tickets</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button class="Button">Add to inventory</button></form><?php endif;?></section>
<?php elseif($page==='login'):?><section class="Panel narrow"><h1>Member Login</h1><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Character Name<input name="username" required></label><label>Password<input type="password" name="password" required></label><button class="Button">Login</button></form><p>New user? <a href="/Register.aspx">Register</a>.</p></section>
<?php elseif($page==='register'):?><section class="Panel narrow"><h1>Create Account</h1><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Character Name<input name="username" maxlength="20" required></label><label>Password<input type="password" name="password" minlength="8" required></label><label>Confirm Password<input type="password" name="confirm" minlength="8" required></label><button class="Button">Register</button></form></section>
<?php elseif($page==='forum'):?><section class="Panel"><h1>Forum</h1><?php if($currentUser):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Topic title<input name="title" maxlength="120" required></label><label>Message<textarea name="body" rows="4" required></textarea></label><button class="Button">Create topic</button></form><?php else:?><p><a href="/Login.aspx">Sign in</a> to post.</p><?php endif;?><table class="Grid"><tr><th>Topic</th><th>Author</th><th>Replies</th><th>Date</th></tr><?php foreach($topics as $t):?><tr><td><?=e($t['title'])?></td><td><?=e($t['username'])?></td><td><?=(int)$t['replies']?></td><td><?=e($t['created_at'])?></td></tr><?php endforeach;?></table></section>
<?php else:?><section class="Panel"><h1>Page not found</h1><a href="/">Return home</a></section><?php endif;?>
<?php require __DIR__.'/../inc/footer.php'; ?>
